import random

def get_word():
    """Generate a random word from a list of words."""
    words = [
        "python",
        "javascript",
        "kotlin",
        "ruby",
        "javascript",
        # Add more words to the list
    ]
    return random.choice(words).lower()

def play_hangman(word):
    """Play a game of Hangman with the given word."""
    guessed_letters = set()
    incorrect_guesses = 0
    num_guesses = 6

    print(f"You have {num_guesses} guesses to guess the word. Good luck!")

    while num_guesses > 0 and "_" in word:
        print(f"You have {num_guesses} guesses remaining. Here's what you know so far:")
        for i, letter in enumerate(word):
            if letter in guessed_letters:
                print(f"{letter} {word[i]}", end=" ")
            else:
                print("_", end=" ")
        print()

        user_guess = input("Enter a letter: ").lower()

        if user_guess in guessed_letters:
            print("You've already guessed that letter. Try again.")
        elif len(user_guess) != 1:
            print("Please enter a single letter.")
        elif user_guess not in "abcdefghijklmnopqrstuvwxyz":
            print("Please enter a lowercase letter.")
        else:
            guessed_letters.add(user_guess)

            if user_guess in word:
                print(f"You guessed a letter! {word}")
            else:
                print(f"Sorry, that letter is not in the word. You have {num_guesses - 1} guesses remaining.")
                incorrect_guesses += 1

        num_guesses -= 1

    if num_guesses == 0:
        print(f"Sorry, you ran out of guesses. The word was {word}.")
    else:
        print(f"Congratulations! You guessed the word in {num_guesses + 1} guesses.")

if __name__ == "__main__":
    word = get_word()
    play_hangman(word)
```

This program generates a random word from a list of words, keeps track of the user's guesses and the number of incorrect guesses, and displays the word with underscores for each letter that the user hasn't guessed yet. The user can enter a single lowercase letter at a time, and the program will check if the letter is in the word and update the display accordingly. If the user runs out of guesses, the program will display the word and inform the user that they lost.
